    return ways(n, memo);
  }

  private int ways(int step, int[] memo) {
    if (step <= 2) return step;
    if (memo[step] != 0) return memo[step];
    memo[step] = ways(step - 1, memo) + ways(step - 2, memo);
    return memo[step];
