    int nextNext = 0;

    for (int i = s.length() - 1; i >= 0; i--) {
      int current = 0;
      if (s.charAt(i) != '0') {
        current = next;
        if (i + 1 < s.length()) {
          int value = (s.charAt(i) - '0') * 10 + (s.charAt(i + 1) - '0');
