class Solution {
  public int longestArithSeqLength(int[] nums) {
    Map<String, Integer> memo = new HashMap<>();
    int best = 2;
    for (int i = 0; i < nums.length; i++) {
      for (int j = i + 1; j < nums.length; j++) {
        best = Math.max(best, 2 + extend(nums, j, nums[j] - nums[i], memo));
      }
    }
    return best;
  }

  private int extend(int[] nums, int index, int diff, Map<String, Integer> memo) {
    String key = index + ":" + diff;
    if (memo.containsKey(key)) return memo.get(key);
    int best = 0;
    for (int next = index + 1; next < nums.length; next++) {
      if (nums[next] - nums[index] == diff) {
        best = Math.max(best, 1 + extend(nums, next, diff, memo));
      }
    }
    memo.put(key, best);
    return best;
  }
}

